/// Gets the NFC_QC Quick_Check value for a code point
/// Returns 0 (Yes), 1 (No), or 2 (Maybe)
pub fn getNfcQc(cp: Codepoint) QcValue {
    if (cp > 0x10FFFF) return 0;
    const block = @as(usize, cp >> 8);
    if (block >= nfcqc_stage1.len) return 0;
    const offset = @as(usize, cp & 0xFF);
    const stage2_idx = nfcqc_stage1[block] + offset;
    if (stage2_idx >= nfcqc_stage2.len) return 0;
    return nfcqc_stage2[stage2_idx];
}
